#!/usr/bin/env python3
"""Append a batch of sudo pairs with dedup, length checks, and stats."""
import json
import sys
import os

OUTPUT = "/Users/aditya/Documents/Icebreaker/privileged-brain/v2/data/synthetic/beginner/beginner_pairs.jsonl"

def load_existing_nls():
    nls = set()
    with open(OUTPUT) as f:
        for line in f:
            line = line.strip()
            if not line:
                continue
            try:
                obj = json.loads(line)
            except:
                continue
            if obj.get("category") == "sudo":
                nls.add(obj["nl"].strip().lower())
    return nls

def count_sudo():
    n = 0
    with open(OUTPUT) as f:
        for line in f:
            line = line.strip()
            if not line:
                continue
            try:
                obj = json.loads(line)
            except:
                continue
            if obj.get("category") == "sudo":
                n += 1
    return n

def main(batch_file, batch_label):
    existing = load_existing_nls()
    with open(batch_file) as f:
        pairs = json.load(f)
    appended = 0
    skipped_dup = 0
    skipped_len = 0
    skipped_format = 0
    with open(OUTPUT, "a") as out:
        for p in pairs:
            nl = p.get("nl", "").strip()
            bash = p.get("bash", "").strip()
            cat = p.get("category", "sudo")
            if not nl or not bash:
                skipped_format += 1
                continue
            if cat != "sudo":
                skipped_format += 1
                continue
            if len(nl) > 200 or len(bash) > 300:
                skipped_len += 1
                continue
            if not bash.startswith("sudo") and "sudo " not in bash[:20]:
                # allow patterns like `echo ... | sudo tee ...`
                if "sudo " not in bash:
                    skipped_format += 1
                    continue
            key = nl.lower()
            if key in existing:
                skipped_dup += 1
                continue
            existing.add(key)
            out.write(json.dumps({"nl": nl, "bash": bash, "category": "sudo"}) + "\n")
            appended += 1
    total = count_sudo()
    print(f"Batch {batch_label}: +{appended} appended (dup={skipped_dup}, len={skipped_len}, fmt={skipped_format}), total sudo = {total}")
    return appended, total

if __name__ == "__main__":
    main(sys.argv[1], sys.argv[2])
